export const badgeCss = ".kalos-badge{font-family:Roboto, "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", ByteSans, Arial, "Helvetica Neue", -apple-system, BlinkMacSystemFont, "noto sans", Helvetica, sans-serif;--badge-neutral-ink:#666666;--badge-neutral-wash:#f3f3f3;--badge-info-ink:#2384ff;--badge-info-wash:#edf4ff;--badge-success-ink:#008a46;--badge-success-wash:#eef9f2;--badge-warning-ink:#9c5d15;--badge-warning-wash:#fef2e3;--badge-purple-ink:#8b2cff;--badge-purple-wash:#f6f0ff;--badge-pink-ink:#d6006e;--badge-pink-wash:#fff0f7;--badge-neutral-solid:#666666;--badge-info-solid:#2384ff;--badge-success-solid:#008a46;--badge-warning-solid:#f19021;--badge-purple-solid:#8b2cff;--badge-pink-solid:#d6006e;--badge-danger-solid:#c4320a;--badge-on-solid:#ffffff;--badge-warning-base:#f19021;--badge-danger-ink:#c4320a;--badge-danger-wash:rgba(240, 68, 56, 0.08);--badge-height-sm:18px;--badge-height-md:20px;--badge-font-sm:11px;--badge-font-md:12px;--badge-radius-sm:4px;--badge-radius-md:4px;--badge-live-duration:1800ms;--badge-padding-x:6px;--badge-gap:4px;--badge-line-height:20px;--badge-dot-size:5px;--badge-dot-space:1.5px}
